type Account = { id: string; email: string; name: string; role?: string }

function useAccount() {
  const [account, setAccount] = useState<Account | null>(() => {
    if (supabase) return null
    try { const saved = localStorage.getItem('dd-account'); return saved ? JSON.parse(saved) as Account : null } catch { return null }
  })
  useEffect(() => {
    if (!supabase) return
    let active = true
    const client = supabase
    const { data: authListener } = client.auth.onAuthStateChange((_event, session) => {
      const user = session?.user
      const next = user ? { id: user.id, email: user.email ?? '', name: user.user_metadata.name ?? user.email ?? 'Member' } : null
      if (!active) return
      setAccount(next)
      if (!next) localStorage.removeItem('dd-account')
    })
    void client.auth.getSession().then(({ data, error }) => {
      if (!active) return
      if (error) throw error
      const user = data.session?.user
      setAccount(user ? { id: user.id, email: user.email ?? '', name: user.user_metadata.name ?? user.email ?? 'Member' } : null)
    }).catch(() => { if (active) setAccount(null) })
    return () => { active = false; authListener.subscription.unsubscribe() }
  }, [])
  const signOut = async () => {
    if (supabase) await supabase.auth.signOut()
    setAccount(null)
    localStorage.removeItem('dd-account')
  }
  return { account, setAccount, signOut }
}

async function passwordDigest(password: string, salt: Uint8Array) {
  const material = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits'])
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: 120000, hash: 'SHA-256' }, material, 256)
  return btoa(String.fromCharCode(...new Uint8Array(bits)))
}
function randomSalt() { const bytes = crypto.getRandomValues(new Uint8Array(16)); return btoa(String.fromCharCode(...bytes)) }

